/**
 * Stem `uniqueSlug` starts from. Empty input stays `item` (projects and other
 * callers). A stem shorter than the minimum is never used — sign-up falls
 * through to `workspace` instead of refusing the person.
 */
export function uniqueSlugBase(input: string): string {
  const slugified = slugify(input);
  if (slugified.length === 0) return "item";
  if (slugified.length < SLUG_MIN_LENGTH) return "workspace";
  return slugified;
}

/**
 * First-workspace stem. Reserved words are left for `uniqueSlug` to suffix;
 * a name that slugifies to nothing usable (too short, or no Latin letters)
 * becomes `workspace`, which `uniqueSlug` suffixes when that one is taken.
 */
export function workspaceSlugStem(name: string): string {
  const base = slugify(name);
  if (base.length < SLUG_MIN_LENGTH) return "workspace";
  return base;
}

/**
 * Derives a slug from `input` that collides with nothing in `taken`, by
 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
 * Never returns a reserved slug or one shorter than the minimum.
 */
export function uniqueSlug(input: string, taken: Iterable<string>): string {
  const base = uniqueSlugBase(input);
  const used = new Set(taken);
  if (!used.has(base) && !isReservedSlug(base) && isValidSlug(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
    if (!used.has(candidate) && !isReservedSlug(candidate) && isValidSlug(candidate)) {
      return candidate;
    }
  }
  throw new InvalidSlugError(base, "exhausted unique suffixes");
}

