/** Addresses are stored and compared lowercased, so casing is not a second account. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * Case-insensitive lookup. A stored mixed-case row still matches the
 * lowercased spelling, and an exact lowercased row wins when both exist.
 */
export async function findUserByEmail(email: string): Promise<User | null> {
  const normalized = normalizeEmail(email);
  const rows = getDb()
    .select()
    .from(users)
    .where(sql`lower(${users.email}) = ${normalized}`)
    .orderBy(asc(users.createdAt))
    .all();
  const row = rows.find((candidate) => candidate.email === normalized) ?? rows[0];
  return row ? toUser(row) : null;
}

