/** Buckets guarding the unauthenticated endpoints. */
const LOGIN_BUCKET = "auth:login";
const REGISTER_BUCKET = "auth:register";
const RESET_BUCKET = "auth:password-reset";

const WORKSPACE_SUFFIX = "'s workspace";

/**
 * `<display name>'s workspace`, shortened from the display name until the
 * whole title fits the organization name limit. The result still ends in
 * the suffix.
 */
export function workspaceNameFor(displayName: string): string {
  let head = displayName;
  let name = `${head}${WORKSPACE_SUFFIX}`;
  while (
    head.length > 0 &&
    !createOrganizationSchema.shape.name.safeParse(name).success
  ) {
    head = head.slice(0, -1);
    name = `${head}${WORKSPACE_SUFFIX}`;
  }
  return name;
}

function isUniqueEmailError(error: unknown): boolean {
  return (
    error instanceof Error &&
    /unique constraint failed: users\.email/i.test(error.message)
  );
}

