export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitError(
      REGISTER_BUCKET,
      verdict.resetAt,
      "Too many sign-up attempts; try again shortly",
    );
  }

  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new DuplicateAccountError();
  }

  let user: User;
  try {
    user = await userRepo.insertUser({
      email: input.email,
      name: input.name,
      passwordHash: await hashPassword(input.password),
    });
  } catch (error) {
    if (isUniqueEmailError(error)) throw new DuplicateAccountError();
    throw error;
  }

  // Stem first so a reserved, tiny, or non-Latin name still yields a slug
  // `createOrganization` can store. The workspace title is shortened to the
  // name limit and always ends in "'s workspace".
  const org = await createOrganization(user.id, {
    name: workspaceNameFor(input.name),
    slug: workspaceSlugStem(input.name),
    plan: "free",
  });

