import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { toActionResult, toAppError } from "@/lib/errors";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { isReservedSlug, isValidSlug } from "@/lib/slug";
import { createOrganizationSchema } from "@/schemas/organization";
import * as memberRepo from "@/server/repositories/member-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import {
  confirmPasswordReset,
  login,
  register,
  requestPasswordReset,
  workspaceNameFor,
} from "@/server/services/auth-service";
import { subscribe } from "@/lib/event-bus";
import { useTemporaryDatabase } from "./server/_support/fixtures";
import type { OrgId } from "@/types/common";

const ANON = "00000000000000000000000000" as OrgId;
const PASSWORD = "Correct1Horse2";

let cleanup: () => void;

beforeAll(async () => {
  resetRateLimits();
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function signUp(name: string, email: string) {
  return register({
    name,
    email,
    password: PASSWORD,
    confirmPassword: PASSWORD,
    acceptTerms: true,
  });
}

describe("sign-up rules", () => {
  it("accepts reserved, short, and non-latin names on the free plan", async () => {
    const joined: string[] = [];
    const off = subscribe("member.joined", () => {
      joined.push("once");
    });

    const cases = ["Admin", "Al", "J", "山田", "A".repeat(80)] as const;
    for (const name of cases) {
      const before = joined.length;
      const { user, org } = await signUp(name, `${name.length}-${name.slice(0, 8)}@Example.com`);
      expect(user.email).toBe(user.email.toLowerCase());
      expect(org.plan).toBe("free");
      expect(org.name.endsWith("'s workspace")).toBe(true);
      expect(org.name.length).toBeLessThanOrEqual(64);
      expect(createOrganizationSchema.shape.name.safeParse(org.name).success).toBe(true);
      expect(isValidSlug(org.slug)).toBe(true);
      expect(isReservedSlug(org.slug)).toBe(false);
      expect(joined.length - before).toBe(1);
      const sub = await subscriptionRepo.findSubscription(org.id);
      expect(sub?.status).toBe("active");
      expect(sub?.plan).toBe("free");
      const members = await memberRepo.listMembers({
        orgId: org.id,
        limit: 10,
        cursor: null,
      });
      expect(members.total).toBe(1);
    }

    off();
    expect(workspaceNameFor("A".repeat(80)).length).toBeLessThanOrEqual(64);
  });

  it("treats email casing as one account and reports a conflict", async () => {
    const first = await signUp("Casey", "Casey@Example.com");
    expect(first.user.email).toBe("casey@example.com");
    await expect(signUp("Casey Two", "casey@example.com")).rejects.toMatchObject({
      code: "conflict",
    });
    const found = await userRepo.findUserByEmail("CASEY@example.com");
    expect(found?.id).toBe(first.user.id);
    const signedIn = await login({
      email: "Casey@Example.com",
      password: PASSWORD,
      rememberMe: false,
    });
    expect(signedIn.user.id).toBe(first.user.id);
    expect(toAppError(await signUp("Nope", "casey@example.com").catch((error) => error)).code).toBe(
      "conflict",
    );
  });

  it("throttles sign-up and sign-in as rate_limited, and keeps reset requests silent", async () => {
    resetRateLimits();
    for (let i = 0; i < 30; i += 1) {
      expect((await consumeRateLimit(ANON, "auth:register")).allowed).toBe(true);
    }
    const limited = await signUp("Limited", "limited@example.com").catch((error) => error);
    expect(toAppError(limited).code).toBe("rate_limited");
    expect(toActionResult(limited).ok).toBe(false);
    expect(await userRepo.findUserByEmail("limited@example.com")).toBeNull();

    resetRateLimits();
    for (let i = 0; i < 30; i += 1) {
      await consumeRateLimit(ANON, "auth:login");
    }
    const loginError = await login({
      email: "casey@example.com",
      password: PASSWORD,
      rememberMe: false,
    }).catch((error) => error);
    expect(toAppError(loginError).code).toBe("rate_limited");

    resetRateLimits();
    for (let i = 0; i < 5; i += 1) {
      await consumeRateLimit(ANON, "auth:password-reset");
    }
    await expect(requestPasswordReset({ email: "casey@example.com" })).resolves.toBeUndefined();
    const confirmError = await confirmPasswordReset({
      token: "t".repeat(20),
      password: PASSWORD,
      confirmPassword: PASSWORD,
    }).catch((error) => error);
    expect(toAppError(confirmError).code).toBe("rate_limited");
  });
});

